from solution import swap_numbers


def test_issue_example_10_20():
    """Example: assert swap_numbers(10,20)==(20,10)."""
    assert swap_numbers(10, 20) == (20, 10)  # swap 10,20 -> (20,10)


def test_issue_reversed_20_10():
    """Rule: swap two numbers."""
    assert swap_numbers(20, 10) == (10, 20)  # swap 20,10 -> (10,20)


def test_issue_same_values():
    """Rule: swap two numbers."""
    assert swap_numbers(5, 5) == (5, 5)  # swap 5,5 -> (5,5)


def test_issue_zero_and_positive():
    """Rule: swap two numbers."""
    assert swap_numbers(0, 5) == (5, 0)  # swap 0,5 -> (5,0)


def test_issue_both_zero():
    """Rule: swap two numbers."""
    assert swap_numbers(0, 0) == (0, 0)  # swap 0,0 -> (0,0)


def test_issue_both_negative():
    """Rule: swap two numbers."""
    assert swap_numbers(-3, -7) == (-7, -3)  # swap -3,-7 -> (-7,-3)


def test_issue_mixed_sign():
    """Rule: swap two numbers."""
    assert swap_numbers(-4, 9) == (9, -4)  # swap -4,9 -> (9,-4)


def test_issue_float_numbers():
    """Rule: swap two numbers."""
    assert swap_numbers(1.5, 2.5) == (2.5, 1.5)  # swap 1.5,2.5 -> (2.5,1.5)


def test_contract_returns_tuple():
    """Contract: example returns tuple (20,10)."""
    assert isinstance(swap_numbers(3, 4), tuple) == True  # isinstance((4,3), tuple) == True


def test_contract_returns_two_elements():
    """Contract: example returns pair (20,10) with two elements."""
    assert len(swap_numbers(3, 4)) == 2  # len((4,3)) = 2
